using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra;
internal sealed class LatticeBcGhostCohomologyModesDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/VertexAlgebra/LatticeBcGhostCohomologyModes.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Integer modes on the actual original BRST cohomology.",
        H("Carrier and hypotheses"),
        Blocks(
            Paragraph(Text("The carrier is the existing OriginalCohomology: the kernel of the unchanged original Q, divided by the pullback of its range into that kernel. Under both Gram inverse equations and rank 26, the existing critical nilpotence theorem places the entire original Q image in the kernel. No relative retract criterion is used.")),
            Paragraph(Text("The exact denominator. Write C = ker(Q) on the full original matter tensor ghost carrier and B = (range(Q)).comap(C.subtype). Then OriginalCohomology is C/B; in ambient-vector notation the denominator is ker(Q) intersect range(Q), not an arbitrary boundary space. This quotient and the mode products below make sense for every D and H. Only after H times Gram = 1, Gram times H = 1 and rank(D) = 26 are all imposed does original_image_in_cycles identify B with the entire original-Q image inside the cycles. Both inverse equations and the rank condition are retained for that physical square-zero interpretation. There is no altered, truncated or conjugated differential.")),
            Paragraph(Text("The original number operator. On an occupation basis vector e_S of the ghost factor, BcGhostNumber.J multiplies by the number of odd occupied sites minus the number of even occupied sites. On a finite linear combination it is the sum of these signed occupation eigenactions, and J_D acts as identity on matter tensor this same J. The b field mode n is physical b(n-1), while the c field mode n is physical c(n+2), for all integer n. The existing J_b/J_c commutators, the site-field divided derivatives and the right-nested signed normal recursion imply the ghost Ward identity. In each residue the ordered sums have finite support separately on v and Jv; map_finsum and finite-support sum subtraction justify the commutator term by term, without a state-independent cutoff. The canonical basisWord and stateField_expansion extend it to every full ghost state. The actual tensor mode convolution uses indices i and n-1-i, and its three finite-support instances extend the identity to arbitrary full tensor states. Thus J_D(Y_D(a)_n v) = Y_D(J_D a)_n v + Y_D(a)_n(J_D v), for every integer n, with no parity or degree-eigenvector premise.")),
            Paragraph(Text("Number stability of the actual pullback quotient. The existing original-charge identity [J_D,Q] = Q says J_D(Qw) = Q(J_D w + w) on arbitrary full states w. It also says Q(J_D u)=0 whenever Qu=0. These are the same J/Q applications supplied in the existing OriginalBrstReassembly namespace, whose local uses here come directly from J_Q_commutator rather than from duplicate named general theorems or a second number operator. Restricting J_D to C gives cycleJ. If a cycle u is the boundary Qw, then J_D u = Q(J_D w+w); hence cycleJ preserves the literal B. Submodule.mapQ therefore defines the endomorphism cohomologyJ on the existing C/B, and cohomologyJ([u]) = [J_D u]. The preimage w need not be a cycle. Number stability itself needs neither Gram inverses nor critical rank.")),
            Paragraph(Text("All-mode quotient covariance. The product at integer mode n is the existing bilinear descent product_n([u],[v]) = [Y_D(u)_n v], for closed representatives u,v. Both boundary-slot obligations are the existing original-Q derivation proofs, including the signed parity splitting for mixed states; the number argument does not replace those obligations by assumptions. Apply the full tensor Ward identity to u,v, use that J_D preserves cycles and B, and project into C/B. Quotient induction in both arguments gives cohomologyJ(product_n(x,y)) = product_n(cohomologyJ(x),y) + product_n(x,cohomologyJ(y)), for arbitrary quotient classes x,y and every integer n. The plus sign is correct because ghost number acts evenly, even when the states have mixed parity. The -1 topological product is a specialization of this all-mode law, not a new quotient product.")),
            Paragraph(Text("Exact integer eigenvalue premises. Let r,s be arbitrary integers. If cohomologyJ(x) = r x and cohomologyJ(y) = s y, with complex scalar casts, quotient covariance and bilinearity imply cohomologyJ(product_n(x,y)) = (r+s) product_n(x,y) for every integer n. In particular, actual original cycles u,v satisfying J_D u = r u and J_D v = s v supply such eigenclasses through the literal quotient map, and their product has degree r+s. No assertion is made that every quotient eigenclass has an exactly homogeneous original representative, or that arbitrary classes split into integer eigenspaces. Those representative-existence and integer direct-sum questions are separate from this conditional consequence. Ghost number is not conformal energy, and no energy positivity premise has been inserted.")),
            Paragraph(Text("Parity, locality and physical scope. The locality supplier is LatticeBcGhostCohomologyLocality, which reopens the LatticeBcGhostCohomologyFields namespace and proves superLocal. It requires parity_p(x)=x and parity_q(y)=y and supplies a locality order killing the supercommutator of the actual quotient fields with exchange sign (-1) raised to p*q, on every input class and all two integer modes. Projected homogeneous original representatives and the actual tensor-field locality prove this statement; no ghost-number decomposition is used. This locality result and the quotient modes do not themselves need critical rank or a Gram inverse, whereas interpreting them as the physical nilpotent original BRST cohomology requires both inverse equations and rank 26. The representative action cohomologyJ([u])=[J_D u] does not establish equality with a separately transported Jbar. No B0 second-order law, bracket Jacobi identity or full VOA/CFT/fusion/string/AdS completion follows from the present number covariance alone; the full-cycle B0 representative remains B0(P0 u), not B0 u on arbitrary full cycles.")),
            Describe.Lean(DescribeId.Create("odd-projections"), DeclarationHandle.Create(Prefix + "Q_parityPart"), H("Actual odd differential and parity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The original Q exchanges the actual parity projections. Arbitrary mixed cycles and boundaries therefore split into actual even and odd cycles and boundaries."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("right-ideal"), DeclarationHandle.Create(Prefix + "cycleMode_boundary_right"), H("Boundary in the input slot"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For a closed mixed state, the signed difference of its projected modes on a boundary preimage is an explicit original-Q preimage of the mode product."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("left-ideal"), DeclarationHandle.Create(Prefix + "cycleMode_boundary_left"), H("Boundary in the state slot"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The actual mixed derivation law gives an explicit original-Q preimage whenever the other argument is closed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("bilinear-product"), DeclarationHandle.Create(Prefix + "product_mk"), H("Genuine complex bilinear descent"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Mathlib LinearMap.liftQ₂ constructs the descended bilinear integer modes after both boundary obligations are proved. Changing either closed representative by an original-Q boundary leaves the quotient result unchanged."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("full-image"), DeclarationHandle.Create(Prefix + "boundaryCycle_class_zero"), H("Every original Q image is a zero class at critical rank"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("This endpoint explicitly retains both Gram inverse equations and rank 26; the square-zero input is the existing theorem for the original Q, not an assumed or conjugated differential."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("truncation"), DeclarationHandle.Create(Prefix + "product_lower_truncation"), H("Pointwise lower truncation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The actual tensor field bound descends on each pair of quotient states. No uniform state-independent cutoff is asserted."))), DescribeRole.Theorem))));
}
